PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer',status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,token_hash TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sites(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,phone TEXT DEFAULT '',address TEXT DEFAULT '',working_hours TEXT DEFAULT '',description TEXT DEFAULT '',logo_url TEXT DEFAULT '',cover_url TEXT DEFAULT '',design TEXT DEFAULT 'default',status TEXT NOT NULL DEFAULT 'active',trial_started_at TEXT,trial_ends_at TEXT,subscription_type TEXT DEFAULT 'trial',subscription_ends_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,site_id TEXT NOT NULL,name TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS menu_items(id TEXT PRIMARY KEY,site_id TEXT NOT NULL,category_id TEXT,name TEXT NOT NULL,description TEXT DEFAULT '',price REAL DEFAULT 0,image_url TEXT DEFAULT '',available INTEGER NOT NULL DEFAULT 1,sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS restaurant_tables(id TEXT PRIMARY KEY,site_id TEXT NOT NULL,name TEXT NOT NULL,capacity INTEGER NOT NULL DEFAULT 2,status TEXT NOT NULL DEFAULT 'available',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reservations(id TEXT PRIMARY KEY,site_id TEXT NOT NULL,table_id TEXT,customer_name TEXT NOT NULL,customer_phone TEXT NOT NULL,reservation_date TEXT NOT NULL,reservation_time TEXT NOT NULL,party_size INTEGER NOT NULL,notes TEXT DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS qr_codes(id TEXT PRIMARY KEY,site_id TEXT NOT NULL,code TEXT,url TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
